package com.taller.user;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/usuarios") public class UserController { private final UserRepository users; private final PasswordEncoder encoder; public UserController(UserRepository u,PasswordEncoder e){users=u;encoder=e;} record Perfil(Long id,String nombre,String email,Role rol,boolean activo){} record Alta(@NotBlank String nombre,@Email String email,@Size(min=8) String password,Role rol){} @GetMapping("/me") Perfil yo(Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return perfil(u);}@GetMapping List<Perfil> listar(){return users.findAll().stream().map(this::perfil).toList();}@PostMapping @ResponseStatus(HttpStatus.CREATED) Perfil alta(@Valid @RequestBody Alta r){if(r.rol()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El rol es obligatorio");if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"El correo ya está registrado");User u=new User();u.setNombre(r.nombre());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRol(r.rol());return perfil(users.save(u));} private Perfil perfil(User u){return new Perfil(u.getId(),u.getNombre(),u.getEmail(),u.getRol(),u.isActivo());}}
